generation_rounds.planner_raw:
{
  "strategy": "Find the final question-state frame that shows the last shape before any solution overlay, then inspect that shape’s vertices/line connections to determine whether it has an Euler trail/circuit and map that directly to the correct option.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO_PATH",
        "query": "question screen showing the last of several line-tracing shapes before any path, highlighting, or worked-solution annotations are added",
        "timestamps": null,
        "num_frames": 3
      },
      "purpose": "Retrieve candidate frames for the last shape in its unsolved question state; multiple frames are needed because retrieval may mix question-state and explanation-state variants.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "ocr",
      "arguments": {
        "frame_path": "<STEP_1:frames>",
        "timestamp": null
      },
      "purpose": "Read any on-screen ordinal labels, prompt text, or option text that can confirm which retrieved frame corresponds to the 'last shape' question screen rather than an explanation frame.",
      "depends_on": [1]
    },
    {
      "step": 3,
      "tool": "spatial_grounder",
      "arguments": {
        "frame_path": "<STEP_1:frames>",
        "timestamp": null,
        "query": "the final line-tracing shape diagram with all visible vertices and connecting line segments"
      },
      "purpose": "Ground the actual diagram across the candidate frames so the refiner can choose the frame-level result that cleanly shows the full last shape and inspect its connection structure.",
      "depends_on": [1]
    }
  ],
  "refinement_instructions": "Use the step-1 frame bundle as the candidate set for the last shape; do not assume the first retrieved frame is correct. Use OCR from step 2 to identify which frame is the actual question-state frame for the last shape (for example, the frame with the prompt/ordinal cue and without worked-solution markings). Then use the per-frame spatial grounding from step 3 on that same frame to reason about the graph structure: count the vertices with odd degree by inspecting how many line segments meet at each visible point. Apply the Euler-path rule explicitly in the rewritten trace: a shape can be traced in one stroke without lifting or retracing iff it has exactly 0 or 2 odd-degree vertices; 0 means a circuit, 2 means a trail; more than 2 means impossible. Map the verified odd-degree count to the answer options exactly, and update the final answer accordingly. If the candidate frames are mixed between raw and annotated states, prefer the raw question-state frame and ignore later explanatory overlays when counting degrees."
}
